CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname = 'school') THEN
        CREATE SCHEMA school;
    END IF;
END $EF$;

CREATE TABLE school."People" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FirstName" character varying(50) NOT NULL,
    "LastName" character varying(50) NOT NULL,
    "Discriminator" character varying(34) NOT NULL,
    "HireDate" date,
    "EnrollmentDate" date,
    CONSTRAINT "PK_People" PRIMARY KEY ("Id")
);

CREATE TABLE school."Departments" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(50) NOT NULL,
    "Budget" numeric(8,2) NOT NULL,
    "StartDate" date NOT NULL,
    "AdministratorId" integer,
    CONSTRAINT "PK_Departments" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Departments_People_AdministratorId" FOREIGN KEY ("AdministratorId") REFERENCES school."People" ("Id") ON DELETE SET NULL
);

CREATE TABLE school."Courses" (
    "Id" integer NOT NULL,
    "Title" character varying(100) NOT NULL,
    "Credits" integer NOT NULL,
    "DepartmentId" integer NOT NULL,
    CONSTRAINT "PK_Courses" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Courses_Departments_DepartmentId" FOREIGN KEY ("DepartmentId") REFERENCES school."Departments" ("Id") ON DELETE RESTRICT
);

CREATE TABLE school."CoursesInstructors" (
    "CourseId" integer NOT NULL,
    "InstructorId" integer NOT NULL,
    CONSTRAINT "PK_CoursesInstructors" PRIMARY KEY ("CourseId", "InstructorId"),
    CONSTRAINT "FK_CoursesInstructors_Courses_CourseId" FOREIGN KEY ("CourseId") REFERENCES school."Courses" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_CoursesInstructors_People_InstructorId" FOREIGN KEY ("InstructorId") REFERENCES school."People" ("Id") ON DELETE CASCADE
);

CREATE TABLE school."CourseStudent" (
    "CoursesId" integer NOT NULL,
    "StudentsId" integer NOT NULL,
    CONSTRAINT "PK_CourseStudent" PRIMARY KEY ("CoursesId", "StudentsId"),
    CONSTRAINT "FK_CourseStudent_Courses_CoursesId" FOREIGN KEY ("CoursesId") REFERENCES school."Courses" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_CourseStudent_People_StudentsId" FOREIGN KEY ("StudentsId") REFERENCES school."People" ("Id") ON DELETE CASCADE
);

CREATE TABLE school."Enrollments" (
    "CourseId" integer NOT NULL,
    "StudentId" integer NOT NULL,
    "Grade" numeric(3,2),
    CONSTRAINT "PK_Enrollments" PRIMARY KEY ("StudentId", "CourseId"),
    CONSTRAINT "FK_Enrollments_Courses_CourseId" FOREIGN KEY ("CourseId") REFERENCES school."Courses" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Enrollments_People_StudentId" FOREIGN KEY ("StudentId") REFERENCES school."People" ("Id") ON DELETE CASCADE
);

CREATE TABLE school."OnlineCourses" (
    "Id" integer NOT NULL,
    "Url" text NOT NULL,
    CONSTRAINT "PK_OnlineCourses" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_OnlineCourses_Courses_Id" FOREIGN KEY ("Id") REFERENCES school."Courses" ("Id") ON DELETE CASCADE
);

CREATE TABLE school."OnsiteCourses" (
    "Id" integer NOT NULL,
    "Location" text NOT NULL,
    "Time" time without time zone NOT NULL,
    CONSTRAINT "PK_OnsiteCourses" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_OnsiteCourses_Courses_Id" FOREIGN KEY ("Id") REFERENCES school."Courses" ("Id") ON DELETE CASCADE
);

